import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as r,c as n,o as s,ag as t,G as i}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const y=JSON.parse(`{"title":"Google Flow","description":"Google's AI creative studio. Generate short clips, a few seconds to a dozen or so long, from an English prompt, then arrange them into a finished film in Scenebuilder. This page explains whether you can use it, how to make a first video in 10 minutes, how credits are charged and how to avoid the common pitfalls.","frontmatter":{"title":"Google Flow","description":"Google's AI creative studio. Generate short clips, a few seconds to a dozen or so long, from an English prompt, then arrange them into a finished film in Scenebuilder. This page explains whether you can use it, how to make a first video in 10 minutes, how credits are charged and how to avoid the common pitfalls.","domain":"product","tags":["coding-agent"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/gemini/flow.md","filePath":"products/gemini/flow.md","lastUpdated":1795764761000}`),d={name:"products/gemini/flow.md"};function l(h,e,c,g,p,u){const o=r("DocDiagram");return s(),n("div",null,[e[0]||(e[0]=t('<h1 id="google-flow" tabindex="-1">Google Flow <a class="header-anchor" href="#google-flow" aria-label="Permalink to &quot;Google Flow&quot;">​</a></h1><blockquote><p>Google&#39;s AI creative studio (the official name is <strong>AI creative studio</strong>). It solves this problem: a frontend engineer needs a video for a landing page, a product launch or an internal review, but has never shot footage and does not want to learn editing software. In Flow, you write one English description, generate a clip of a few seconds to a dozen or so, then arrange the clips into a finished film.</p><p>It <strong>does not write code</strong>. Use it for landing-page films, product demo videos and storyboards; for a page you can click, use <a href="./canvas.html">Canvas</a>.</p><p>Entry point: <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">labs.google/fx/tools/flow</a>. Help centre: <a href="https://support.google.com/flow" target="_blank" rel="noreferrer">support.google.com/flow</a>.</p></blockquote><p>The UI steps, credits and region information on this page were checked page by page against the official help centre <strong>as of 2026-11-24</strong>. These details change; trust what your own interface shows.</p><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td><strong>Who it is for</strong></td><td>Engineers who write frontend code, have never made a video and have not used a generative video tool</td></tr><tr><td><strong>Prerequisites</strong></td><td>A Google account; 18 or older and age-verified; located in an officially supported country or region; a Chromium-based browser such as Chrome or Edge on your computer</td></tr><tr><td><strong>Non-goals</strong></td><td>No editing software; no Veo / Imagen API calls, which are the business of <a href="./ai-studio.html">AI Studio</a>; no Flow Music, which makes songs and music videos and has a separate credit system</td></tr></tbody></table><h2 id="what-you-will-be-able-to-do" tabindex="-1">What you will be able to do <a class="header-anchor" href="#what-you-will-be-able-to-do" aria-label="Permalink to &quot;What you will be able to do&quot;">​</a></h2><ul><li>Decide <strong>whether you can use it</strong>: what each of the three requirements, age, region and plan, asks for.</li><li><strong>Make a first video in 10 minutes</strong> and download it as a file.</li><li><strong>Pick the right generation mode</strong> by what you have to hand: only a sentence, one image, character reference images, or an existing video.</li><li>Use Character, ingredients and start and end frames to <strong>keep characters and scenes consistent across clips</strong>, then arrange the clips into a finished film in Scenebuilder.</li><li><strong>Understand how credits are charged</strong> and recognise the common errors: which step spends credits and which does not, and which official statement covers each pitfall.</li></ul><h2 id="can-you-use-it-age-region-language-plan" tabindex="-1">Can you use it: age, region, language, plan <a class="header-anchor" href="#can-you-use-it-age-region-language-plan" aria-label="Permalink to &quot;Can you use it: age, region, language, plan&quot;">​</a></h2><p>Google&#39;s official pages list three conditions: age verified and 18 or older; being in a supported region; and, to use some features, a Google AI subscription. Each in turn.</p><h3 id="age-18-or-older-and-age-verified" tabindex="-1">Age: 18 or older, and age-verified <a class="header-anchor" href="#age-18-or-older-and-age-verified" aria-label="Permalink to &quot;Age: 18 or older, and age-verified&quot;">​</a></h3><p>The help centre&#39;s own words: &quot;Make sure your age is verified. You must be 18 years of age or older.&quot; Age verification is attached to your Google account.</p><h3 id="region-mainland-china-is-not-on-the-list-hong-kong-macau-and-taiwan-are" tabindex="-1">Region: mainland China is not on the list; Hong Kong, Macau and Taiwan are <a class="header-anchor" href="#region-mainland-china-is-not-on-the-list-hong-kong-macau-and-taiwan-are" aria-label="Permalink to &quot;Region: mainland China is not on the list; Hong Kong, Macau and Taiwan are&quot;">​</a></h3><p><a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">Where you can use Google Flow</a> says: &quot;You can use the Google Flow Desktop platform and download the Google Flow mobile app in these countries and regions.&quot; As of 2026-11-24, that page lists the supported countries and regions in alphabetical order.</p><table tabindex="0"><thead><tr><th>Where I am</th><th>On the supported list</th><th>Evidence (wording on the official page)</th></tr></thead><tbody><tr><td>Mainland China</td><td><strong>Not on it</strong></td><td>The list is alphabetical and goes from <code>Chile</code> straight to <code>Colombia</code>; <code>China</code> does not appear anywhere on the page</td></tr><tr><td>Hong Kong</td><td><strong>On it</strong></td><td><code>Hong Kong</code></td></tr><tr><td>Macau</td><td><strong>On it</strong></td><td><code>Macau</code></td></tr><tr><td>Taiwan</td><td><strong>On it</strong></td><td><code>Taiwan</code></td></tr></tbody></table><p>Two related official statements:</p><ul><li><strong>A VPN does not help</strong>: &quot;VPNs will not enable access in unsupported regions.&quot;</li><li><strong>Buying AI Pro does not guarantee access</strong>: &quot;Google Flow is not currently available in all countries where Google AI Pro is offered.&quot; Google suggests checking the supported list before you buy a subscription.</li></ul><p>Some features are also restricted by region. The same page states:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Regions where it is not available</th></tr></thead><tbody><tr><td>Editing an uploaded video</td><td>European Economic Area (EEA), Switzerland, the United Kingdom</td></tr><tr><td>Avatar (a model of your own likeness)</td><td>European Economic Area (EEA), Switzerland, the United Kingdom</td></tr><tr><td>Buying AI credits</td><td>Japan</td></tr></tbody></table><h3 id="language-the-interface-has-simplified-and-traditional-chinese-english-is-recommended-for-prompts" tabindex="-1">Language: the interface has Simplified and Traditional Chinese; English is recommended for prompts <a class="header-anchor" href="#language-the-interface-has-simplified-and-traditional-chinese-english-is-recommended-for-prompts" aria-label="Permalink to &quot;Language: the interface has Simplified and Traditional Chinese; English is recommended for prompts&quot;">​</a></h3><p>The official page says &quot;Google Flow is currently available in these languages&quot;, and the list includes <code>Chinese (Simplified &amp; Traditional)</code> and <code>Cantonese</code>. The interface language follows your Google Account settings: &quot;You can update your preferred language in your Google Account settings.&quot;</p><p>For prompts, the official wording is a recommendation to use English, not a rule that English is the only option: &quot;For best results with our tools, we recommend using English prompts. While some of our products may support prompts in other languages, the quality of the generated output may vary depending on the language and complexity of the prompt.&quot;</p><blockquote><p>An earlier version of this page said &quot;You can only prompt Flow in English, and the replies are in English too&quot;, and cited the <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro benefits page</a>. Checked on 2026-11-24: that sentence (&quot;Only English is supported for prompts and instructions&quot;) belongs to the <strong>Google Antigravity</strong> section of that page, not to Flow. Flow&#39;s own pages say only &quot;recommend English&quot;.</p></blockquote><h3 id="plan-you-can-try-it-without-a-subscription" tabindex="-1">Plan: you can try it without a subscription <a class="header-anchor" href="#plan-you-can-try-it-without-a-subscription" aria-label="Permalink to &quot;Plan: you can try it without a subscription&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Plan</th><th>What you can use</th><th>Flow credits (as of 2026-11-24)</th></tr></thead><tbody><tr><td>No subscription</td><td>Basic video generation and editing. Omni Flash 1.2 generates 3 to 10 seconds; Veo 3.1 Lite generates 4, 6 or 8 seconds</td><td>50 per day</td></tr><tr><td>Google AI Plus / Pro / Ultra (two Ultra tiers)</td><td>All features. Omni Flash 1.2 generates 3 to 15 seconds; Omni Extend; upscaling from 360p to 1080p (4K on Ultra only); creating and remixing Tools</td><td>50 per day, plus 200 / 1,000 / 10,000 / 25,000 per month (Plus, Pro, then the two Ultra tiers)</td></tr><tr><td>Eligible Workspace plans</td><td>Official wording: &quot;get access at no extra charge to Google Flow with 50 daily credits&quot;</td><td>50 per day</td></tr></tbody></table><p>For the Workspace row, the plans Google lists are Business Starter / Standard / Plus, Enterprise Starter / Standard / Plus, G Suite Legacy Free Edition, Education Standard / Plus and Google AI Pro for Education.</p><p>Not subscribing comes with one restriction: during peak hours (officially &quot;roughly 2 PM to 5 PM UTC&quot;, which is 22:00 to 01:00 the next day Beijing time) you may be unable to generate videos. You can still generate images and use Agent then.</p><h3 id="where-to-use-it-the-desktop-web-version-has-the-most-features" tabindex="-1">Where to use it: the desktop web version has the most features <a class="header-anchor" href="#where-to-use-it-the-desktop-web-version-has-the-most-features" aria-label="Permalink to &quot;Where to use it: the desktop web version has the most features&quot;">​</a></h3><ul><li>The <strong>desktop web version</strong> has the most features. Official: &quot;For the most powerful editing features, go to Google Flow on a computer.&quot;</li><li>The <strong>mobile app</strong> is for creating on the go. Official: &quot;For creation on the go, download the Google Flow app.&quot;</li><li><strong>Features found only on the web version</strong>: Frames to Video and Omni Extend on Omni Flash 1.2 (both marked officially &quot;Currently only available at Google Flow on web&quot;); Tools (&quot;Tools are currently available on web &amp; PC only&quot;).</li><li><strong>Browser</strong>: use a Chromium-based one; Google&#39;s examples are Google Chrome or Edge. Google warns that other browsers and mobile &quot;are not yet fully optimized&quot;, so you may hit bugs.</li></ul><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h2><p>Start with the vocabulary. The left column holds the terms you will meet in the interface and the help centre.</p><table tabindex="0"><thead><tr><th>Term</th><th>One-line explanation</th><th>Why you need it</th></tr></thead><tbody><tr><td><strong>project</strong></td><td>A container that holds all the assets for one film</td><td>Assets, Agent sessions and Tools are all stored per project; switching project means switching film</td></tr><tr><td><strong>asset</strong></td><td>Each image and each video generated in or uploaded to the project</td><td>Adding to a prompt, placing on the timeline and downloading all work at the level of the asset</td></tr><tr><td><strong>generation</strong></td><td>One triggered model call</td><td>Credits are charged per generation, not per click</td></tr><tr><td><strong>take</strong></td><td>One generation may return several results; each result is one candidate</td><td>More candidates give you more room to choose, and the credit charge multiplies too</td></tr><tr><td><strong>frame</strong></td><td>A single image in a video; the start frame and the end frame decide where a video begins and ends</td><td>To make the end of shot A meet the start of shot B, you rely on frames</td></tr><tr><td><strong>ingredients</strong></td><td>Reference images or reference videos handed to the model together with the prompt</td><td>Keeps the same person or the same object looking the same across shots</td></tr><tr><td><strong>character</strong></td><td>A bundled set of visual and audio references that has been given a name</td><td>No need to upload the same batch of images again every time</td></tr><tr><td><strong>Scenebuilder</strong></td><td>The place where several clips are arranged into one timeline</td><td>A single clip runs only a few seconds to a dozen or so; the finished film is assembled here</td></tr><tr><td><strong>scene</strong></td><td>A sequence of clips arranged in Scenebuilder</td><td>Preview and download both work at the level of the scene</td></tr><tr><td><strong>Extend</strong></td><td>Adds a few more seconds after a video</td><td>When a good shot is too short, you do not have to redo the whole clip</td></tr><tr><td><strong>Jump to</strong></td><td>Moves a character or object into a new setting without changing its appearance</td><td>The same character changes location without a new description</td></tr><tr><td><strong>aspect ratio</strong></td><td>The width-to-height ratio of the picture</td><td>A landing-page banner and a portrait phone screen need different ratios</td></tr><tr><td><strong>resolution</strong></td><td>360p drafts and 720p as standard, then scalable to 1080p or 4K</td><td>360p is cheap and suits testing the composition first</td></tr><tr><td><strong>credits</strong></td><td>The allowance charged when you generate a video</td><td>Decides how many shots you can make in a given period</td></tr><tr><td><strong>Tools</strong></td><td>Small tools that you describe in natural language and Flow generates by writing code</td><td>Repetitive jobs such as caption bars and changing the aspect ratio</td></tr><tr><td><strong>Agent</strong></td><td>The conversational assistant in the prompt box</td><td>Helps you write prompts, list shots and produce candidates in batches</td></tr></tbody></table><p>A few that are easy to confuse, spelled out below.</p><h3 id="project-and-asset" tabindex="-1">project and asset <a class="header-anchor" href="#project-and-asset" aria-label="Permalink to &quot;project and asset&quot;">​</a></h3><p>To create a project, click <strong>+ New project</strong>. The left sidebar lets you find assets by type: All media, Images, Videos, Characters, Scenes, Uploads. Assets can be dragged into a <strong>Collection</strong> (like a folder, and it can be nested).</p><h3 id="generation-and-take" tabindex="-1">generation and take <a class="header-anchor" href="#generation-and-take" aria-label="Permalink to &quot;generation and take&quot;">​</a></h3><p>The official blog has used the word take (&quot;the first take isn&#39;t the final one&quot;), but the steps in the help centre say output (<code>Number of outputs you want</code>). The credits page stresses one sentence: &quot;The Google Flow/AI credit costs below are per generation, not per request. Some product features will create multiple generations per request. For example, in Google Flow, you can make a single request that may generate 2 videos.&quot; In other words, asking for 2 candidates costs the credits of 2 generations.</p><h3 id="frame" tabindex="-1">frame <a class="header-anchor" href="#frame" aria-label="Permalink to &quot;frame&quot;">​</a></h3><p>The interface text for the start frame is <strong>+ Add start frame.</strong> and for the end frame it is <strong>+ Add end frame.</strong> You can also pull a frame out of a video: pause on a frame, hover and click <strong>Save frame</strong>.</p><h3 id="ingredients-and-character" tabindex="-1">ingredients and character <a class="header-anchor" href="#ingredients-and-character" aria-label="Permalink to &quot;ingredients and character&quot;">​</a></h3><p>Official statement on ingredients: &quot;You can consistently use the same images for your character and key objects from one clip to the next with the use of ingredients.&quot;</p><p>Official statement on character: &quot;You can bundle specific visual and audio references into a single, reusable character. Your character&#39;s face, clothing, and voice remain strictly consistent across multiple generations without needing to upload the same images every time.&quot;</p><p>The difference: ingredients are references you attach <strong>each time you generate</strong>; a character is a bundled reference you <strong>create once and refer to again and again</strong>. Type <code>@</code> followed by the character&#39;s name in the prompt to refer to it.</p><h3 id="scenebuilder-extend-and-jump-to" tabindex="-1">Scenebuilder, Extend and Jump to <a class="header-anchor" href="#scenebuilder-extend-and-jump-to" aria-label="Permalink to &quot;Scenebuilder, Extend and Jump to&quot;">​</a></h3><p>The Scenebuilder capabilities Google lists: arranging several clips, changing their order, trimming the start and end of each clip with handles, previewing the whole sequence and downloading the scene. The official blog calls it &quot;your in-Flow storyboard, where you assemble individual clips into a complete narrative&quot;.</p><p>Official statement on Extend: &quot;If you need a scene to be longer, you can create more footage and add it to the end of your original clip.&quot;</p><p>Only the official blog has defined Jump to (2025-06-25): &quot;Transition a character or object to a completely new setting while preserving their appearance from the previous shot.&quot;</p><h3 id="aspect-ratio-and-resolution" tabindex="-1">aspect ratio and resolution <a class="header-anchor" href="#aspect-ratio-and-resolution" aria-label="Permalink to &quot;aspect ratio and resolution&quot;">​</a></h3><p>The help centre&#39;s models page says &quot;Both aspect ratios&quot; for every mode, without naming which two. The official launch post for Veo 3.1 Lite says the model &quot;offers flexible framing for landscape (16:9) and portrait (9:16) ratios&quot;.</p><p>For resolution, Omni Flash can produce drafts at 360p, and Google writes that its credits are one third of those at 720p. Subscribers can upscale 360p to 1080p, and Ultra subscribers can go up to 4K.</p><h3 id="tools-and-agent" tabindex="-1">Tools and Agent <a class="header-anchor" href="#tools-and-agent" aria-label="Permalink to &quot;Tools and Agent&quot;">​</a></h3><ul><li><strong>Tools</strong>: the official definition is &quot;Build custom, reusable tools and mini-apps using natural language in Google Flow&quot;. Flow ships with a set of prebuilt Tools provided by Google.</li><li><strong>Agent</strong>: the official definition is &quot;a built-in creative collaborator&quot;, which helps you sort out ideas, revise prompts and steer the generation process through natural conversation.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Read the next diagram with this question in mind: the sentence I type and the reference image I supply — which model takes over each of them, and how do they end up as a clip on the timeline?</p>',52)),i(o,{src:"/diagrams/google-flow-pipeline.en.svg",alt:"This diagram runs left to right in four stages and answers one question: when you type a sentence or supply a reference image, which model takes it, and how does it become a clip on the timeline? Stage 1 is input, three things: the text prompt, frames (a start frame and an end frame), and ingredients (characters, scenes, objects). Stage 2 is the models. There are two video models, Omni Flash from Gemini Omni and Veo 3.1 Lite from Veo 3.1. They generate and edit video and support conversational iteration, and every generation spends credits, counted per second or per generation. The image models are the Nano Banana family (Pro, 2.1, 2 Lite). They generate and edit images, spend no credits, and follow a daily cap instead. Stage 3 is output: the video models produce candidate clips, and the image models produce images. Stage 4 is the finished film, which is the Scenebuilder timeline. There are six sets of connections. First, the text prompt goes straight into the video models. Second, frames and ingredients can enter the video models together with the same generation. Third, the video models produce candidate clips, and the image models produce images. Fourth, the arrow from candidate clips to Scenebuilder is labelled Add to Scene: only the candidates you pick enter the timeline; the ones you do not pick never do. Fifth, a dashed line along the bottom runs left from the output images back to the input: a generated image can be reused as the start frame, end frame, or ingredient of a later video generation. Sixth, the two-headed dashed line along the top, between the models and Scenebuilder, is Extend: it goes from the end of an existing clip back to the video models, and the continuation it generates returns to the timeline. Inside Scenebuilder, clips sit in order; you can drag them into a different order and trim their start and end. This diagram leaves out which models support which generation mode, because one mode is usually supported by several models, so input is not drawn as one-to-one with any model. It also leaves out specific credit amounts, API call paths, and Flow Music, whose credit system is separate.",width:1080,lang:"en"}),e[1]||(e[1]=t(`<blockquote><p><strong>What the diagram is based on:</strong> The four-stage split and the objects in each stage come from three help centre articles, <a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos</a>, <a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">Edit &amp; build scenes</a> and <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Credits &amp; per-generation cost</a>. Model names follow the <a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">official models page</a>, as of 2026-11-24. The diagram keeps the objects of the four stages, the direction of the six sets of connections, and the rule that credits are charged only at the video-model layer. It leaves out which models each generation mode supports (one mode is usually supported by several models, so input is not drawn as one-to-one with the models), the specific credit amounts, API call paths, and Flow Music, whose credit system is separate. Solid lines are the main path of one generation; dashed lines are reuse and Extend.</p></blockquote><p>Four relationships in the diagram are worth remembering:</p><ol><li><strong>The input decides the path</strong>. With text only, it goes straight to the video models. With a reference image, the image can serve as a frame or as an ingredient and enter the video models together with the same generation.</li><li><strong>Images are raw material for video</strong>. An image generated by Nano Banana can be used directly as the ingredient, start frame or end frame of a later video generation. Google says these image models exist to &quot;create frames and ingredients for your projects&quot;; frames pulled out of a video work the same way.</li><li><strong>There is more than one model, and credits are charged at the model layer</strong>. Videos are generated by Omni Flash 1.2 or Veo 3.1 Lite and cost credits; images are generated by the Nano Banana family and do not.</li><li><strong>The finished film takes shape in Scenebuilder</strong>. The candidate clips from each generation first land in the project; only the ones you pick go onto the timeline.</li></ol><h2 id="make-your-first-video-in-10-minutes" tabindex="-1">Make your first video in 10 minutes <a class="header-anchor" href="#make-your-first-video-in-10-minutes" aria-label="Permalink to &quot;Make your first video in 10 minutes&quot;">​</a></h2><p>Goal: make an 8-second, 720p video from scratch and download it. By the official credits page, this step costs <strong>24 credits</strong> (Omni Flash 1.2 at 720p is 3 credits per second). The day&#39;s 50 credits are enough.</p><h3 id="step-1-open-flow-and-create-a-project" tabindex="-1">Step 1: Open Flow and create a project <a class="header-anchor" href="#step-1-open-flow-and-create-a-project" aria-label="Permalink to &quot;Step 1: Open Flow and create a project&quot;">​</a></h3><ul><li><strong>What to do</strong>: open <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">Flow</a> in Chrome or Edge, sign in with your Google account (age, region and credits are all tied to the account), then click <strong>+ New project</strong>.</li><li><strong>What you will see</strong>: an empty project and a prompt box.</li><li><strong>Why</strong>: assets are stored per project. On a first run you do not need to create a character or upload reference images beforehand.</li></ul><h3 id="step-2-write-a-one-sentence-prompt" tabindex="-1">Step 2: Write a one-sentence prompt <a class="header-anchor" href="#step-2-write-a-one-sentence-prompt" aria-label="Permalink to &quot;Step 2: Write a one-sentence prompt&quot;">​</a></h3><ul><li><strong>What to do</strong>: describe the scene in English in the prompt box. Google asks you to be clear about five things: &quot;Be specific about the subject, action, environment, lighting, and style.&quot; The example below was written by this site; it is not official text:</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A slow wide shot of a dark studio desk at night. A slim laptop in the center</span></span>
<span class="line"><span>shows a plain dark dashboard with soft blue charts. A warm desk lamp on the</span></span>
<span class="line"><span>left lights the keyboard; the rest of the room falls into soft shadow. Fine</span></span>
<span class="line"><span>dust drifts in the light. The camera pushes in very slowly. No people, no text.</span></span></code></pre></div><ul><li><strong>What you will see</strong>: your text in the prompt box.</li><li><strong>Why</strong>: this is Text to video mode, and one sentence is enough to get started.</li></ul><h3 id="step-3-switch-to-video-and-choose-the-settings" tabindex="-1">Step 3: Switch to video and choose the settings <a class="header-anchor" href="#step-3-switch-to-video-and-choose-the-settings" aria-label="Permalink to &quot;Step 3: Switch to video and choose the settings&quot;">​</a></h3><ul><li><strong>What to do</strong>: click the model name, click <strong>Video</strong>, then choose four settings: <strong>Aspect ratio</strong>, <strong>Number of outputs you want</strong> (choose 1 the first time), <strong>The model you want to use</strong> (choose Omni Flash 1.2) and <strong>Generation length</strong> (choose 8 seconds).</li><li><strong>What you will see</strong>: these four video settings appear in the prompt box.</li><li><strong>Why</strong>: Google writes &quot;By default, Google Flow sets the model to Nano Banana Pro&quot;. The default is an image model, so without switching you generate an image. Double the number of candidates and the credit charge doubles too.</li></ul><h3 id="step-4-generate-and-wait-for-the-result" tabindex="-1">Step 4: Generate and wait for the result <a class="header-anchor" href="#step-4-generate-and-wait-for-the-result" aria-label="Permalink to &quot;Step 4: Generate and wait for the result&quot;">​</a></h3><ul><li><strong>What to do</strong>: click <strong>Generate</strong>.</li><li><strong>What you will see</strong>: the results appear in the project grid as individual cards (official: &quot;your generations now appear as individual tiles&quot;). While you wait, a card may show <strong>Pending</strong>.</li><li><strong>Why</strong>: take a first look at what was generated before deciding whether to continue.</li><li><strong>If you get stuck</strong>: if a Pending or error card stays where it is, check the system notifications in the top right corner. Google states that generations that failed because of a policy or a credit limit need to be retried or deleted by hand.</li></ul><h3 id="step-5-pick-one-to-keep" tabindex="-1">Step 5: Pick one to keep <a class="header-anchor" href="#step-5-pick-one-to-keep" aria-label="Permalink to &quot;Step 5: Pick one to keep&quot;">​</a></h3><ul><li><strong>What to do</strong>: if you are happy with it, keep it. The first generation is already in the project by itself; the help centre has no separate save button for it.</li><li><strong>What you will see</strong>: select <strong>Videos</strong> in the left sidebar and you will find the video.</li><li><strong>Why</strong>: <strong>Save to Project</strong> is for a different case. You have edited the video and want to keep one of the older versions: open the video, hover over the version in the <strong>History</strong> panel on the right, and click <strong>Save to Project</strong>. Google states that an older version must be saved before it can go into Scenebuilder.</li></ul><h3 id="step-6-download" tabindex="-1">Step 6: Download <a class="header-anchor" href="#step-6-download" aria-label="Permalink to &quot;Step 6: Download&quot;">​</a></h3><ul><li><strong>What to do</strong>: hover over the asset, click <strong>More</strong>, then <strong>Download</strong>, and choose the file type. For a GIF, choose <strong>270p</strong>.</li><li><strong>What you will see</strong>: the browser downloads a video file or a GIF.</li><li><strong>Why</strong>: the finished clip has to go into your web page or your presentation, and downloading is the way out of Flow.</li></ul><p><strong>What this cost</strong>: go back to the top right corner and click your profile picture; your remaining credits sit under it; 8 seconds at 720p should have used up 24 credits. Two ways to spend less: switch to Veo 3.1 Lite, where one generation is 10 credits (non-Ultra); or drop Omni Flash 1.2 to 360p, where 8 seconds is 8 credits. When you dislike the result, change the prompt first instead of retrying again and again. A retry is simply another generation, and it is charged as usual.</p><h2 id="use-each-generation-mode" tabindex="-1">Use each generation mode <a class="header-anchor" href="#use-each-generation-mode" aria-label="Permalink to &quot;Use each generation mode&quot;">​</a></h2><p>The <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro benefits page</a> lists these modes: Text to video, Ingredients to video, Frames to video, Text to image and Image to image. The help centre&#39;s models page adds Video to Video editing and Extend videos (Omni Extend). The landing page spells the last two as Video Extension and Video-to-video editing. The subheadings on this page follow the help centre&#39;s names.</p><p>Start with an overview table, then go through the modes one at a time. The content comes from <a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">Learn about Google Flow models &amp; supported features</a>, as of 2026-11-24.</p><table tabindex="0"><thead><tr><th>Mode</th><th>What you have</th><th>Omni Flash 1.2</th><th>Veo 3.1 Lite</th></tr></thead><tbody><tr><td>Text to video</td><td>A sentence of description</td><td>Supported, 3 to 10 seconds (up to 15 with a subscription)</td><td>Supported, 4, 6 or 8 seconds</td></tr><tr><td>Frames to video</td><td>A start frame, or a start frame and an end frame</td><td>Supported, 3 to 10 seconds; web only</td><td>Supported; with a start frame only, or with both a start and an end frame</td></tr><tr><td>Ingredients to video</td><td>Reference images of a character or an object</td><td>Supported, 3 to 10 seconds</td><td>Supported, 8 seconds only</td></tr><tr><td>Video to video</td><td>An existing video</td><td>Supported, 3 to 10 seconds</td><td>Not supported</td></tr><tr><td>Video extension</td><td>A video that has already been generated</td><td>Supported, extends by 3 to 10 seconds; subscription required; web only</td><td>Not supported</td></tr></tbody></table><p>Veo 3.1 Fast, Veo 3.1 Quality and Omni Flash 1.1 <strong>retire on 2026-12-05</strong>. Google advises starting new projects directly on Omni Flash 1.2 or Veo 3.1 Lite.</p><h3 id="text-to-video" tabindex="-1">Text to video <a class="header-anchor" href="#text-to-video" aria-label="Permalink to &quot;Text to video&quot;">​</a></h3><ul><li><strong>Good for</strong>: starting a shot from zero, with no reference at all.</li><li><strong>Prepare</strong>: one English description that is clear about the subject, action, environment, lighting and style.</li><li><strong>Steps</strong>: see Steps 2 to 4 in the previous section.</li><li><strong>How to write the prompt</strong>: see &quot;How to write prompts&quot; at the end of this section.</li><li><strong>Common failure</strong>: several candidates come out at once and the credit charge multiplies. Set <strong>Number of outputs you want</strong> to 1.</li></ul><h3 id="frames-to-video" tabindex="-1">Frames to video <a class="header-anchor" href="#frames-to-video" aria-label="Permalink to &quot;Frames to video&quot;">​</a></h3><ul><li><strong>Good for</strong>: you have one image (a design mock-up, a screenshot, a frame from the previous clip) and want to set it in motion; or you want to control both the beginning and the end of a video.</li><li><strong>Prepare</strong>: one image as the start frame; to control the end as well, prepare a second image as the end frame. Official reminder: &quot;Product feature availability may differ by country/region of use. Certain image types may not be supported.&quot;</li><li><strong>Steps</strong> (official steps): <ol><li>In the project&#39;s prompt box, click the model name.</li><li>Click <strong>Video</strong>, then <strong>Frames</strong>.</li><li>Drag the image onto <strong>+ Add start frame.</strong> For an end frame, drag another image onto <strong>+ Add end frame.</strong></li><li>In the prompt, describe the action or transition that happens between the two frames.</li><li>Choose the video settings and click <strong>Generate</strong>.</li></ol></li><li><strong>How to write the prompt</strong>: focus on &quot;how things change&quot; and do not restate the static content already in the image. For an example, see the &quot;Product demo&quot; template.</li><li><strong>Common failure</strong>: you cannot find Frames in the mobile app. Frames to Video on Omni Flash 1.2 is currently offered on the web version only.</li></ul><h3 id="ingredients-to-video" tabindex="-1">Ingredients to video <a class="header-anchor" href="#ingredients-to-video" aria-label="Permalink to &quot;Ingredients to video&quot;">​</a></h3><ul><li><strong>Good for</strong>: several shots that need the same person, the same object or the same scene.</li><li><strong>Prepare</strong>: reference images. Google suggests images of the subject or product <strong>on a plain or a segmented (cut-out) background</strong> (&quot;provide subject or product references on a plain or segmented background&quot;); keep other people out of scene and style reference images.</li><li><strong>Steps</strong> (official steps): <ol><li>In the prompt box, click the model name.</li><li>Click <strong>Video</strong>, then <strong>Ingredients</strong>.</li><li>Add reference material; choose one of four ways: drag reference images or reference videos into Flow from your device; type <code>@</code> followed by the asset name in the prompt box to use an asset already in the project; click <strong>Add</strong> and pick an asset from the project; click <strong>Add</strong>, then <strong>Upload media</strong>, to upload a file.</li><li>State in the prompt how each reference is to be used. Official example: the references are a woman, a lava lamp and a foggy street, and the prompt is <code>The woman, whose torso is the lava lamp, walks down the foggy street</code>.</li><li>Choose the video settings and click <strong>Generate</strong>.</li></ol></li><li><strong>How to write the prompt</strong>: the text has to work with the reference images, not contradict them, and it has to point to the material you supplied. Official: &quot;Your text prompt should complement, not contradict, your visual inputs.&quot;</li><li><strong>Common failures</strong>: <ul><li>You chose a length other than 8 seconds with Veo 3.1 Lite. On that model, Ingredients supports only 8 seconds.</li><li>You added a voice reference and got an error. Official: &quot;You can add voice references only to video generations that use ingredients.&quot; The entry point is <strong>Add</strong>, then <strong>Voices</strong>, under the Omni Flash model.</li><li>The character still changed. Switch to Character instead; see the next section.</li></ul></li></ul><h3 id="text-to-image" tabindex="-1">Text to image <a class="header-anchor" href="#text-to-image" aria-label="Permalink to &quot;Text to image&quot;">​</a></h3><ul><li><strong>Good for</strong>: producing the key stills first to fix the character, the scene and the composition, then using them as frames or reference material for video.</li><li><strong>Prepare</strong>: one description of the image.</li><li><strong>Steps</strong> (official steps): enter the project, click the model name, click <strong>Image</strong>, choose <strong>Image aspect ratio</strong>, <strong>Number of outputs you want</strong> and the model, write the prompt, optionally add ingredients, and click <strong>Generate</strong>.</li><li><strong>How to write the prompt</strong>: Google only asks that it &quot;describes the image you want to create in detail&quot;.</li><li><strong>Common failure</strong>: assuming that generating images costs credits. Official: &quot;Generating and upscaling images in Google Flow does not currently use your monthly Google Flow credits or AI credits.&quot; Images follow a daily cap instead; see &quot;Credits&quot; later on this page.</li></ul><h3 id="image-to-image" tabindex="-1">Image to image <a class="header-anchor" href="#image-to-image" aria-label="Permalink to &quot;Image to image&quot;">​</a></h3><ul><li><strong>Good for</strong>: you already have an image and want to change its background, change its style or crop it.</li><li><strong>Prepare</strong>: the image in the project.</li><li><strong>Steps</strong>, two official paths: <ol><li>Edit the image in conversation. Open <strong>Agent</strong>, drag the images into the prompt box (several at a time is fine), write what to change, and click <strong>Generate</strong>. Official example prompt: <code>Make these black and white.</code> The changes are saved automatically to that asset&#39;s version stack.</li><li>Crop. Open the image, click <strong>Crop</strong> on the left, choose the crop area, and click <strong>Crop</strong>.</li></ol></li><li><strong>To refer to another image in the project</strong>: hover over that image, click <strong>More</strong>, then <strong>Add to prompt</strong>.</li><li><strong>Common failure</strong>: you cannot find the old image after editing. It is not lost; the <strong>History</strong> panel on the right holds every previous version and the prompt used at the time.</li></ul><h3 id="video-to-video" tabindex="-1">Video to video <a class="header-anchor" href="#video-to-video" aria-label="Permalink to &quot;Video to video&quot;">​</a></h3><ul><li><strong>Good for</strong>: you have a video that you shot or generated, and want to change the lighting, add something or swap the background.</li><li><strong>Prepare</strong>: a <code>.mov</code>, <code>.mp4</code>, <code>.avi</code> or <code>.wmv</code> file of at most 60 seconds and 1 GB. Anything over 30 seconds must be trimmed to 30 seconds or less inside Flow.</li><li><strong>Steps</strong> (three official steps): <ol><li>Set the video model to Omni Flash 1.2. Open the generation settings at the bottom of the prompt box, click <strong>Video</strong>, click the video model and choose <strong>Omni Flash 1.2</strong>.</li><li>Upload, drag in or select the video. Google states that Flow processes it, converts the format and runs a safety check automatically.</li><li>Click the video you want to edit, select a segment of up to 10 seconds in the trimming window (up to 15 seconds for Plus / Pro / Ultra subscribers), write the prompt, optionally add ingredients, and click <strong>Generate</strong>. You can then add further prompts or ingredients, with up to 3 rounds of conversation that keep the context.</li></ol></li><li><strong>How to write the prompt</strong>: write only what to change and keep the rest. Official examples: <code>Change the lighting to a cinematic sunset</code>, <code>Add a text overlay that says &#39;Coming Soon&#39;</code>.</li><li><strong>Common failures</strong>: <ul><li>You are told that your region is not supported. Google writes that the feature is &quot;only available in certain countries&quot;.</li><li>You cannot change what a person says. In all regions, Google does not support editing or generating the speech of people in an uploaded video; changing lines, adding dialogue and dubbing are all out. To make the person speak, use a prompt to generate a new clip.</li><li>The credit charge is larger than you expected. Official: &quot;Edits cost the same credits per second as standard generations.&quot;</li></ul></li></ul><h3 id="video-extension" tabindex="-1">Video extension <a class="header-anchor" href="#video-extension" aria-label="Permalink to &quot;Video extension&quot;">​</a></h3><ul><li><strong>Good for</strong>: a shot that is good but too short.</li><li><strong>Prepare</strong>: a Google AI Plus, Pro or Ultra subscription; the video you want to extend; optionally up to 3 reference images.</li><li><strong>Steps</strong> (official steps): enter the project, click the clip you want to extend, click <strong>Extend</strong> at the bottom, choose the extension length, describe in the prompt box how the action continues, optionally add up to 3 image references to keep characters and the environment consistent, and click <strong>Generate</strong>.</li><li><strong>How to write the prompt</strong>: write the action that comes next. The official blog explained the principle: &quot;It analyzes the final frames and continues the action&quot;.</li><li><strong>Common failures</strong>: <ul><li>The button does not work. Official: &quot;This feature is only available to Google AI Plus, Pro &amp; Ultra subscribers on the Omni Flash 1.2 model.&quot; Veo Extend retired on 2026-11-05.</li><li>An extended clip can no longer be edited with insert, remove, camera and similar edits.</li><li>Credits are charged per added second: 1 credit per second at 360p, 3 credits per second at 720p.</li></ul></li></ul><h3 id="how-to-write-prompts-official-principles" tabindex="-1">How to write prompts: official principles <a class="header-anchor" href="#how-to-write-prompts-official-principles" aria-label="Permalink to &quot;How to write prompts: official principles&quot;">​</a></h3><p>The section &quot;Best practices &amp; advanced tips when generating in Google Flow&quot; of the help centre article <a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos in Google Flow</a> lists three:</p><ol><li><strong>Prepare clean ingredients</strong>. Put subject or product references on a plain or a cut-out background; keep extra people out of scene and style references unless you want them.</li><li><strong>Avoid conflicting guidance</strong>. The text prompt should add to the images you supply, never override them; the prompt has to point to the frames or reference material you gave; when all the references look consistent, the model blends them more easily.</li><li><strong>Iterate with Gemini</strong>. Send your prompts, images or even videos to Gemini and have it rewrite the prompt and branch out with ideas.</li></ol><p>The official blog post <a href="https://blog.google/innovation-and-ai/products/flow-video-tips/" target="_blank" rel="noreferrer">5 tips for getting started with Flow</a> (2025-06-25) adds the elements a prompt should contain:</p><ul><li><strong>Subject and action</strong>: who or what, doing what.</li><li><strong>Composition and camera motion</strong>: use <code>wide shot</code> or <code>close-up</code> to set the shot size, and <code>tracking shot</code> or <code>aerial view</code> to set the camera movement.</li><li><strong>Location and lighting</strong>: do not write only &quot;a room&quot;; write where the light comes from and what falls into shadow.</li><li><strong>Alternative styles</strong>: you can specify styles such as <code>stop motion</code> or <code>clay animation</code>.</li><li>When you have Gemini write several shots that lead into each other, tell it explicitly to repeat every key detail from the earlier prompts.</li></ul><h3 id="how-to-write-prompts-three-templates" tabindex="-1">How to write prompts: three templates <a class="header-anchor" href="#how-to-write-prompts-three-templates" aria-label="Permalink to &quot;How to write prompts: three templates&quot;">​</a></h3><p>All three prompts below are <strong>examples written by this site</strong>, not official text. They share one structure: subject, action, environment, lighting, style, exclusions. Replace the parts item by item, following the table under each prompt.</p><p><strong>Template 1: Landing-page film</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A slow wide shot of a dark studio desk at night. A slim laptop in the center</span></span>
<span class="line"><span>shows a plain dark dashboard with soft blue charts. A warm desk lamp on the</span></span>
<span class="line"><span>left lights the keyboard; the rest of the room falls into soft shadow. Fine</span></span>
<span class="line"><span>dust drifts in the light. The camera pushes in very slowly. No people, no text.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Part</th><th>Matching text</th><th>What it does</th></tr></thead><tbody><tr><td>Shot size and camera movement</td><td><code>A slow wide shot</code>, <code>The camera pushes in very slowly</code></td><td>Matches the official Composition and camera motion; the slower the movement, the better it works as a background</td></tr><tr><td>Subject</td><td><code>A slim laptop in the center shows a plain dark dashboard</code></td><td>Matches Subject; the interface is given as an outline only, so do not expect the model to draw your real product</td></tr><tr><td>Environment, lighting and style</td><td><code>dark studio desk at night</code>, <code>A warm desk lamp on the left</code>, <code>Fine dust drifts in the light</code></td><td>Matches Location and lighting; one light source sets the night-time look, and the drifting dust adds a little motion to a still image</td></tr><tr><td>Exclusions</td><td><code>No people, no text.</code></td><td>Your own copy will be layered over the background video, so no text should appear in the frame</td></tr></tbody></table><p><strong>Template 2: Product demo</strong> (use with Frames to video, with a real screenshot as the start frame)</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Start from the uploaded screenshot of a web app dashboard. Keep the layout,</span></span>
<span class="line"><span>colors and every UI element exactly as they are. A cursor moves to the top</span></span>
<span class="line"><span>right button, clicks it, and a dropdown menu opens with a soft fade. The page</span></span>
<span class="line"><span>stays sharp and still apart from that one interaction. Slow, smooth motion.</span></span>
<span class="line"><span>No new text, no camera movement.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Part</th><th>Matching text</th><th>What it does</th></tr></thead><tbody><tr><td>Anchor to the reference image</td><td><code>Start from the uploaded screenshot</code></td><td>Matches the official tip that &quot;the prompt has to point to the frames you gave&quot;</td></tr><tr><td>Protected parts</td><td><code>Keep the layout, colors and every UI element exactly as they are</code></td><td>Stops the model from redrawing the interface; matches &quot;text must not conflict with the reference image&quot;</td></tr><tr><td>Action</td><td><code>A cursor moves to the top right button, clicks it</code></td><td>One clip performs one operation only; matches Subject and action</td></tr><tr><td>Exclusions</td><td><code>No new text, no camera movement.</code></td><td>Limits what can change and reduces distortion</td></tr></tbody></table><p><strong>Template 3: Feature illustration</strong> (abstract motion graphics, good for explaining a flow)</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Three rounded rectangular cards float in a row on a soft light gray</span></span>
<span class="line"><span>background. A small blue dot travels from the first card to the second, then</span></span>
<span class="line"><span>to the third, leaving a thin glowing line behind it. Each card lifts slightly</span></span>
<span class="line"><span>when the dot arrives. Flat, clean motion graphics, soft shadows, gentle</span></span>
<span class="line"><span>easing. No text.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Part</th><th>Matching text</th><th>What it does</th></tr></thead><tbody><tr><td>Subject</td><td><code>Three rounded rectangular cards float in a row</code></td><td>Abstract shapes stand in for the three objects in your feature</td></tr><tr><td>Action</td><td><code>A small blue dot travels from the first card to the second</code></td><td>Makes the order of events clear</td></tr><tr><td>Style</td><td><code>Flat, clean motion graphics, soft shadows, gentle easing</code></td><td>Matches Alternative styles; the motion-graphics look is closer to a frontend interface</td></tr><tr><td>Exclusions</td><td><code>No text.</code></td><td>Copy and numbers are overlaid with HTML, which makes them easy to change and localise</td></tr></tbody></table><h2 id="join-clips-into-a-finished-film" tabindex="-1">Join clips into a finished film <a class="header-anchor" href="#join-clips-into-a-finished-film" aria-label="Permalink to &quot;Join clips into a finished film&quot;">​</a></h2><p>One generation gives you only a few seconds to a dozen or so: Omni Flash 1.2 makes 3 to 10 seconds, up to 15 with a subscription; Veo 3.1 Lite makes 4, 6 or 8 seconds. A finished film has to join several shots and keep characters and scenes matching from shot to shot. This is Flow&#39;s core value over &quot;one clip per generation&quot;.</p><p>The steps below walk the whole path with one example: the same character appears in three shots of 8 seconds each.</p><h3 id="step-1-fix-the-character-and-the-scene" tabindex="-1">Step 1: Fix the character and the scene <a class="header-anchor" href="#step-1-fix-the-character-and-the-scene" aria-label="Permalink to &quot;Step 1: Fix the character and the scene&quot;">​</a></h3><p>Three official mechanisms; choose as you need:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>How to create it</th><th>How to refer to it</th><th>Good for</th></tr></thead><tbody><tr><td><strong>Character</strong></td><td>Select <strong>Characters</strong> on the left; when you already have characters, click <strong>New Character</strong>. Write a description, upload or generate 1 to 2 images (you need at least 1 to use it), click <strong>Generate</strong>; then name it, choose a voice and click <strong>Done</strong></td><td>In the prompt, type <code>@</code> followed by the character&#39;s name, for example <code>@CaptainZoro walking through a futuristic city</code></td><td>A character that appears again and again across the film</td></tr><tr><td><strong>ingredients</strong></td><td>Drag the reference images into the prompt box each time you generate</td><td>State in the prompt how each reference is to be used</td><td>An object or scene that appears in only a few shots</td></tr><tr><td><strong>Avatar</strong></td><td>In the profile menu at the top right, click <strong>Create avatar</strong>; start on a computer and finish by scanning a QR code with your phone</td><td>Type <code>@me</code> in the prompt</td><td>You are the person on screen</td></tr></tbody></table><p>Avatar is not available in the European Economic Area, the United Kingdom or Switzerland.</p><h3 id="step-2-produce-the-key-stills-first" tabindex="-1">Step 2: Produce the key stills first <a class="header-anchor" href="#step-2-produce-the-key-stills-first" aria-label="Permalink to &quot;Step 2: Produce the key stills first&quot;">​</a></h3><p>Use Text to image to produce the reference stills for your characters and scenes first. The official blog has described how images and video connect: with Nano Banana built in, you can &quot;create high-fidelity images and instantly use them as ingredients and frames for Veo video generations without ever leaving Flow&quot;. Images do not cost credits.</p><h3 id="step-3-generate-shot-by-shot" tabindex="-1">Step 3: Generate shot by shot <a class="header-anchor" href="#step-3-generate-shot-by-shot" aria-label="Permalink to &quot;Step 3: Generate shot by shot&quot;">​</a></h3><p>Generate each shot with Ingredients to video or Frames to video. Check the composition at 360p first (1 credit per second), then produce the final version at 720p once you are happy.</p><h3 id="step-4-make-the-shots-join-up" tabindex="-1">Step 4: Make the shots join up <a class="header-anchor" href="#step-4-make-the-shots-join-up" aria-label="Permalink to &quot;Step 4: Make the shots join up&quot;">​</a></h3><ul><li><strong>Use the end of one shot as the start of the next</strong>. Open shot A, pause on the frame where the join should be, hover and click <strong>Save frame</strong>. Google states that the saved frame can be used in later generations as an ingredient, start frame or end frame. Then set it as the start frame of shot B.</li><li><strong>The shot is too short</strong>. Click the clip, click <strong>Extend</strong> at the bottom and add 3 to 10 seconds; you can attach up to 3 reference images to keep the characters and the environment consistent.</li><li><strong>The same character changes scene</strong>. The official blog&#39;s definition of <strong>Jump to</strong> is in &quot;Core concepts&quot;. The current help centre does not document its entry point, so check that it is still in your interface before you rely on it.</li></ul><h3 id="step-5-arrange-the-clips-in-scenebuilder" tabindex="-1">Step 5: Arrange the clips in Scenebuilder <a class="header-anchor" href="#step-5-arrange-the-clips-in-scenebuilder" aria-label="Permalink to &quot;Step 5: Arrange the clips in Scenebuilder&quot;">​</a></h3><ol><li>Hover over a finished clip, click <strong>More</strong>, then <strong>Add to Scene</strong>.</li><li>Open the scene (you will find it under <strong>Scenes</strong> in the left sidebar) and drag the clips into order.</li><li>Drag the handles at both ends to trim the start and end of each clip.</li><li>Preview the whole sequence.</li><li>Download the scene.</li></ol><h3 id="step-6-take-the-finished-film-with-you" tabindex="-1">Step 6: Take the finished film with you <a class="header-anchor" href="#step-6-take-the-finished-film-with-you" aria-label="Permalink to &quot;Step 6: Take the finished film with you&quot;">​</a></h3><p>Download the scene to get a video file. To publish to YouTube: a single clip can be sent straight from Flow by clicking <strong>More</strong> and then <strong>Publish to YouTube</strong>; a Scenebuilder sequence cannot. Google requires you to download it as a single file first, then upload it through YouTube Studio.</p><h2 id="custom-tools-and-agent" tabindex="-1">Custom Tools and Agent <a class="header-anchor" href="#custom-tools-and-agent" aria-label="Permalink to &quot;Custom Tools and Agent&quot;">​</a></h2><h3 id="tools-build-a-small-tool-in-natural-language" tabindex="-1">Tools: build a small tool in natural language <a class="header-anchor" href="#tools-build-a-small-tool-in-natural-language" aria-label="Permalink to &quot;Tools: build a small tool in natural language&quot;">​</a></h3><p><strong>What it is</strong>: you describe what you need in one sentence, and Flow writes the code and builds the interface. Google&#39;s example is &quot;Make an image filter app with a slider for grayscale and hue shift.&quot; The uses listed on the landing page are caption overlays, changing the aspect ratio, storyboards and shaders.</p><p><strong>Who can use it</strong>: Google is explicit.</p><ul><li>Using prebuilt Tools: all users.</li><li>Creating and remixing: requires a Google AI Plus, Pro or Ultra subscription. Official: &quot;If you&#39;re not subscribed, you can still explore and use pre-built tools.&quot;</li><li>Platform: web and PC only.</li></ul><p><strong>How to build the simplest tool</strong> (official steps):</p><ol><li>Enter the project, click <strong>Tools</strong> on the left, then <strong>Create Tool</strong>.</li><li>Describe the tool you want in the prompt box. Example from this site, not official text: <code>A tool that adds a caption bar to the bottom of a clip, with an editable text field.</code></li><li>Click <strong>Generate</strong>.</li><li>Check the interface. When the agent has finished building, click <strong>Save</strong>.</li></ol><p><strong>After you build it</strong>:</p><ul><li><strong>Edit</strong>: open the Tool, click <strong>Edit</strong>, describe on the right how the code should change, and click <strong>Generate</strong>.</li><li><strong>Share</strong>: click <strong>Share</strong> at the top right, then <strong>Copy link</strong>. Google warns that anyone with the link can see the Tool&#39;s code, name and thumbnail. The link shares only the version that existed when the link was created; later changes do not sync. The only way to stop sharing is to delete the Tool.</li><li><strong>Pin, Favorite, Remix tool</strong>: pin it to the current project, make it available globally, and make a copy to change yourself, respectively.</li></ul><p><strong>Credits</strong>: media generated by a Tool costs Flow credits as usual. Google states that when running a Tool may cost credits, Flow always shows a warning banner. There is a daily limit on how many Tools you can create; the help centre does not list a separate credit charge for &quot;creating&quot;.</p><h3 id="agent-the-conversational-assistant-in-the-prompt-box" tabindex="-1">Agent: the conversational assistant in the prompt box <a class="header-anchor" href="#agent-the-conversational-assistant-in-the-prompt-box" aria-label="Permalink to &quot;Agent: the conversational assistant in the prompt box&quot;">​</a></h3><p><strong>What it is</strong>: Google calls it &quot;a built-in creative collaborator&quot;. The landing page describes it as a project-level creative partner that helps you explore and iterate. The official blog adds that it is built on Gemini models.</p><p><strong>What it can do</strong> (official list):</p><ul><li><strong>Brainstorm and plan</strong>: lists shots, makes mood boards and turns a vague idea into a usable prompt.</li><li><strong>Generate new media</strong>: ask it to generate a video or an image, and it picks a suitable model.</li><li><strong>Edit assets directly</strong>: ask it to edit the assets selected in the project.</li><li><strong>Batch generate</strong>: generates several variations of one asset at a time.</li><li><strong>Organize your assets</strong>: renames files, sorts assets into a Collection and deletes unused assets.</li></ul><p><strong>How to use it</strong>:</p><ol><li>Enter the project and click <strong>Agent</strong> in the prompt box to open it. Click again to close.</li><li>To open the side conversation panel, click <strong>Expand</strong>.</li><li>Write your request. To attach references, drag assets from your device or the project into the prompt box, or click <strong>Add</strong> to select or upload them.</li><li>Click <strong>Generate</strong>.</li></ol><p><strong>Three settings to know</strong>:</p><ul><li><strong>Confirm before generating</strong>. By default, Agent asks you before any action that spends credits. Google warns that once you choose <strong>Never</strong>, it generates and spends credits for you without stopping to confirm. Keep <strong>Always</strong>.</li><li><strong>Agent Instructions</strong>. Click <strong>Agent Instructions</strong> and then <strong>Add instruction</strong> at the bottom of the prompt box; you can add a reference image and write rules so that Agent behaves consistently across the whole project.</li><li><strong>Sessions</strong>. Conversations are saved automatically as Sessions, kept separate per project. Click <strong>Menu</strong> at the top of the side panel to open, create, rename or delete a session. Deleting a session clears the conversation only; the generated assets remain.</li></ul><p><strong>Credits</strong>: media generated by Agent costs credits as usual and is saved automatically into the project that is currently open. Agent conversations themselves currently cost no credits; they follow a daily query limit specific to each plan.</p><h2 id="real-world-use-cases" tabindex="-1">Real-world use cases <a class="header-anchor" href="#real-world-use-cases" aria-label="Permalink to &quot;Real-world use cases&quot;">​</a></h2><p>The three most common scenarios for a frontend engineer. The methods are this site&#39;s own, derived from the official steps; they are not official use cases.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Modes used</th><th>Expected output</th></tr></thead><tbody><tr><td>Landing-page background video</td><td>Text to image to set the look, Text to video to make the clip</td><td>An 8 to 10 second MP4, plus a few lines of HTML</td></tr><tr><td>Product demo clip</td><td>Frames to video mainly, joined in Scenebuilder</td><td>A 15 to 30 second scene, downloaded as a single video</td></tr><tr><td>Animated storyboard for a PM demo</td><td>Agent lists the shots, 360p drafts, joined in Scenebuilder</td><td>A scene of 3 to 5 shots</td></tr></tbody></table><h3 id="landing-page-background-video" tabindex="-1">Landing-page background video <a class="header-anchor" href="#landing-page-background-video" aria-label="Permalink to &quot;Landing-page background video&quot;">​</a></h3><ul><li><strong>What you want</strong>: a looping banner background that does not compete with the text.</li><li><strong>How</strong>: use Template 1 from &quot;How to write prompts&quot; to generate 8 to 10 seconds. Exclude people and text in the prompt, and overlay the heading and copy on the video with HTML. Subscribers can upscale the finished clip to 1080p; upscaling 1 to 10 seconds costs no credits.</li><li><strong>Expected output</strong>: one <code>.mp4</code> file, plus the markup below.</li></ul><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Background video: it must be muted to autoplay; the poster holds the space until the video loads --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">video</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hero-bg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> autoplay</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> muted</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loop</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> playsinline</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> preload</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;metadata&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> poster</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/hero-poster.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/hero.mp4&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;video/mp4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">video</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Two reminders:</p><ul><li>The help centre does not say that Flow can generate a video that loops cleanly from end to start. Check the join yourself by watching the clip.</li><li>A clip may carry native audio (with <strong>Return silent videos</strong> switched on in the project settings, all videos are generated silent), so the page must include <code>muted</code>; otherwise the browser&#39;s autoplay policy may block it.</li></ul><h3 id="product-demo-clip" tabindex="-1">Product demo clip <a class="header-anchor" href="#product-demo-clip" aria-label="Permalink to &quot;Product demo clip&quot;">​</a></h3><ul><li><strong>What you want</strong>: 15 to 30 seconds that demonstrate two or three operations of one feature.</li><li><strong>How</strong>: set a real screenshot as the start frame and set it in motion the way Template 2 does. One clip performs one operation; arrange several clips in Scenebuilder.</li><li><strong>Expected output</strong>: one scene, downloaded as a single video file.</li><li><strong>A boundary to know</strong>: the interface the model generates is &quot;drawn&quot;, not a real screen recording of your product. That is good enough for a demo to a PM or inside the team. For an official external demo, use a real screen recording and use Flow clips only for the opening and transitions.</li></ul><h3 id="animated-storyboard-for-a-pm-demo" tabindex="-1">Animated storyboard for a PM demo <a class="header-anchor" href="#animated-storyboard-for-a-pm-demo" aria-label="Permalink to &quot;Animated storyboard for a PM demo&quot;">​</a></h3><ul><li><strong>What you want</strong>: several screens of one feature set in motion in order, for a review discussion.</li><li><strong>How</strong>: first have Agent list the shots, then turn each shot into a prompt. Draft each shot first with Omni Flash 1.2 at 360p, at 1 credit per second; 4 shots of 8 seconds come to 32 credits. Upscale the ones you pick; for subscribers, upscaling 1 to 10 seconds to 1080p costs no credits. When the same character has to run through the whole piece, create a Character first.</li><li><strong>Expected output</strong>: a scene of 3 to 5 shots, plus a set of storyboard prompts you can implement as written.</li></ul><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>The figures come from <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Manage your Google Flow credits</a> as of 2026-11-24, and are <strong>not</strong> copied from third-party blogs.</p><table tabindex="0"><thead><tr><th>Tier</th><th>Flow credits</th></tr></thead><tbody><tr><td>No subscription</td><td><strong>50 per day</strong> (trial; unused daily credits do not roll over)</td></tr><tr><td>AI Plus</td><td><strong>200 per month</strong> (plus 50 per day)</td></tr><tr><td>AI Pro</td><td><strong>1,000 per month</strong> (plus 50 per day)</td></tr><tr><td>AI Ultra $100 (Ultra 5x on this site)</td><td><strong>10,000 per month</strong> (plus 50 per day)</td></tr><tr><td>AI Ultra $200 (Ultra 20x on this site)</td><td><strong>25,000 per month</strong> (plus 50 per day)</td></tr></tbody></table><p>Key points:</p><ul><li>The monthly credits for subscribers are <strong>extra</strong>. Official wording: &quot;With or without a subscription, you receive 50 Google Flow credits per day. Subscribers receive extra Google Flow credits&quot;.</li><li>Paid tiers refresh on the <strong>billing cycle</strong>, and unused monthly credits <strong>do not roll over</strong>.</li><li>The daily credits refresh is triggered by the first generation of the day. Google&#39;s example: your first use is on 12 August, and the next batch of 50 credits is available on 13 August.</li><li>After the allocation runs out, Plus / Pro / Ultra can buy extra AI credits to keep going (except in Japan). The same AI credits also work in <a href="./antigravity.html">Antigravity</a>.</li><li>Official: &quot;To generate content in Google Flow, you need to use Google Flow credits or AI credits.&quot; Credits are shared across the account; switching device does not switch the ledger.</li><li>Check the balance: click your profile picture at the top right; the remaining credits sit under it. Plus / Pro / Ultra can also see a breakdown of charges and the next refresh date.</li></ul><p>The whole subscription table for the four tiers (storage, model multiplier, Cloud credit and so on) lives <strong>only</strong> in the <a href="./gemini-cheatsheet.html#subscription-tiers">cheatsheet</a>.</p><h3 id="which-actions-cost-credits" tabindex="-1">Which actions cost credits <a class="header-anchor" href="#which-actions-cost-credits" aria-label="Permalink to &quot;Which actions cost credits&quot;">​</a></h3><p>Google warns that &quot;Limits are subject to change at any time&quot;. Check the latest prices in <strong>Settings</strong> at the top right of the prompt box.</p><table tabindex="0"><thead><tr><th>Action</th><th>Charged</th><th>How much (as of 2026-11-24)</th></tr></thead><tbody><tr><td>Generate or edit video with Omni Flash 1.2</td><td>Yes</td><td>1 credit per second at 360p; 3 credits per second at 720p. All users can generate up to 10 seconds</td></tr><tr><td>Generate 11 to 15 seconds with Omni Flash 1.2</td><td>Yes</td><td>Subscribers only. For the part beyond 10 seconds, 2 credits per second at 360p and 6 credits per second at 720p</td></tr><tr><td>Generate 4, 6 or 8 seconds with Veo 3.1 Lite</td><td>Yes</td><td>10 credits per generation; 5 credits per generation for Ultra subscribers</td></tr><tr><td>Lower Priority mode on Veo 3.1 Lite</td><td>No</td><td>Ultra 20x subscribers and family group managers only</td></tr><tr><td>Omni Extend</td><td>Yes</td><td>Subscribers only. For every 1 second added, 1 credit at 360p and 3 credits at 720p</td></tr><tr><td>Upscale 360p to 720p or 1080p</td><td>No for 1 to 10 seconds</td><td>Subscribers only. 1 credit per second for the part beyond 10 seconds</td></tr><tr><td>Upscale to 4K</td><td>Yes</td><td>Ultra only. A flat 50 credits for 1 to 10 seconds; 5 credits per second for the part beyond 10 seconds</td></tr><tr><td>Generate 8 seconds with Veo 3.1 Quality (retiring soon)</td><td>Yes</td><td>100 credits per generation for all users</td></tr><tr><td>Generate or upscale images</td><td>No</td><td>Follows the daily cap; see the next table</td></tr><tr><td>Agent conversations</td><td>No</td><td>Each plan has a daily query limit; media generated by Agent costs credits as usual</td></tr><tr><td>Create a Tool</td><td>Not listed by Google</td><td>There is a daily limit on how many you can create; media generated by a Tool costs credits as usual</td></tr><tr><td>A generation fails, or trips the safety filter</td><td>No</td><td>Credits are charged when the generation starts and returned within an hour</td></tr><tr><td>Retry</td><td>Yes</td><td>Inferred from the official &quot;costs are per generation, not per request&quot;; not an official sentence</td></tr><tr><td>Save a version, save a frame, download, arrange in Scenebuilder</td><td>No charge listed by Google</td><td>The credits page lists no charge for any of these</td></tr></tbody></table><p>The daily caps for images come from <a href="https://support.google.com/flow/answer/16729550" target="_blank" rel="noreferrer">Create &amp; edit images in Flow</a>:</p><table tabindex="0"><thead><tr><th>Model or action</th><th>No subscription</th><th>AI Plus and Pro</th><th>AI Ultra</th></tr></thead><tbody><tr><td>Nano Banana Pro</td><td>20 per day</td><td>100 per day</td><td>500 per day</td></tr><tr><td>Nano Banana 2.1 and 2 Lite (shared)</td><td>400 per day</td><td>1,000 per day</td><td>1,000 per day</td></tr><tr><td>2K upscale</td><td>200 per day</td><td>200 per day</td><td>200 per day</td></tr><tr><td>4K upscale</td><td>Not available</td><td>Not available</td><td>200 per day</td></tr></tbody></table><p>The daily cap resets 24 hours after the first time you use that model on a given day. An image generation that fails or is blocked by the safety filter does not count towards the daily cap.</p><h2 id="when-to-use-it-and-when-not-to" tabindex="-1">When to use it, and when not to <a class="header-anchor" href="#when-to-use-it-and-when-not-to" aria-label="Permalink to &quot;When to use it, and when not to&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to…</th><th>Use</th><th>Do not use Flow</th></tr></thead><tbody><tr><td>A landing-page / launch / product-demo <strong>video</strong></td><td><strong>Flow</strong></td><td>Canvas produces a clickable page, not a finished film</td></tr><tr><td>Give a product manager a <strong>clickable prototype</strong> within half an hour</td><td><a href="./canvas.html">Canvas</a></td><td>Flow does not do DOM or interaction</td></tr><tr><td>Get the chosen design into the repository</td><td><a href="./antigravity.html">Antigravity</a></td><td>Flow does not change code or open a PR</td></tr><tr><td>Songs / music videos / a generative score</td><td><a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">Flow Music</a> (credits are <strong>separate</strong> from Flow)</td><td>Do not treat Flow video credits as music credits</td></tr></tbody></table><p>The Flow Music row rests on an official statement: &quot;Google Flow Music credits are separate from your Google AI credits.&quot;</p><p>A useful combination: try three interaction directions in Canvas, pick one, and hand it to Antigravity to implement in the project. When you need to present the feature to others, make an 8 to 10 second demo clip in Flow.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Google calls it an <strong>AI creative studio</strong>: you plan, generate and refine in natural language, on top of Google&#39;s generative models.</p><p>The landing page currently lists three model families:</p><table tabindex="0"><thead><tr><th>Model</th><th>Official one-liner</th></tr></thead><tbody><tr><td><strong>Gemini Omni</strong></td><td>Creates and edits video from any input reference (real or generated); stresses world understanding, multimodality and conversational editing</td></tr><tr><td><strong>Nano Banana</strong></td><td>Image generation and fine-grained editing; stresses subject consistency, text rendering and reasoning</td></tr><tr><td><strong>Veo 3.1</strong></td><td>Video generation; stresses physics, realism and prompt adherence, with native audio and extended controls</td></tr></tbody></table><p>The help centre uses more specific model names, which line up with the families like this:</p><table tabindex="0"><thead><tr><th>Family (the landing page&#39;s name)</th><th>Specific models in the help centre (as of 2026-11-24)</th><th>Status</th></tr></thead><tbody><tr><td>Gemini Omni</td><td>Omni Flash 1.2; Omni Flash 1.1</td><td>1.1 retires on 2026-12-05</td></tr><tr><td>Veo 3.1</td><td>Veo 3.1 Lite; Veo 3.1 Fast; Veo 3.1 Quality</td><td>Fast and Quality retire on 2026-12-05</td></tr><tr><td>Nano Banana</td><td>Nano Banana Pro; Nano Banana 2.1; Nano Banana 2 Lite</td><td>Image models, used to generate frames and reference material</td></tr></tbody></table><p><strong>What it can do</strong>, from the capabilities listed on the <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">product landing page</a> and in the <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Pro benefits page</a>:</p><ul><li><strong>Generation modes</strong>: Text to video, Frames to video, Ingredients to video, Text to image, Image to image</li><li><strong>Refinement</strong>: Video Extension, Video-to-video editing, Scenebuilder</li><li><strong>Cast</strong>: Characters, Avatars</li><li><strong>Agent</strong>: described officially as a project-level creative partner that helps you explore and iterate</li><li><strong>Custom Tools</strong>: build tools in natural language (caption overlays, changing the aspect ratio, storyboards, shaders); share and remix. The free tier can only <strong>use</strong> existing Tools; <strong>creating</strong> them starts at Plus</li></ul><p><strong>Outputs carry a watermark</strong>. Official: &quot;All outputs generated in Google Flow using Veo, Omni, or Nano Banana include invisible SynthID watermarks.&quot; You control the visible watermark with the &quot;Visible watermarking&quot; switch in the profile drop-down menu. Users who live in India, South Korea or Vietnam and are not on Ultra 20x get a visible watermark automatically.</p><p><strong>Commercial use</strong>: Google&#39;s answer is that the Terms of Service decide, and the terms say Google claims no ownership of the generated content.</p><p>It is off the coding main line. The counterpart in the Claude family is <a href="./../claude/claude-design.html">Claude Design</a>: Design hands off an interface prototype; Flow hands off film you can publish.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><p>Every row names its official source. Unless another source is given, the source is one of seven help centre pages: <a href="https://support.google.com/flow/answer/16353333" target="_blank" rel="noreferrer">Get started</a>, <a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos</a>, <a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">Edit &amp; Scenebuilder</a>, <a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">Models &amp; supported features</a>, <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Credits</a>, <a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">Available regions</a> and <a href="https://support.google.com/flow/answer/17093911" target="_blank" rel="noreferrer">Agent</a>.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>It will not open, or it says your region is unsupported</td><td>Mainland China is not on the supported list</td><td>Check the <a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">available regions</a>. A VPN <strong>cannot</strong> get around this: Google writes &quot;VPNs will not enable access in unsupported regions&quot;</td></tr><tr><td>You have a VPN on and get &quot;We noticed some unusual activity&quot;</td><td>Google asks you to turn off VPN and proxy</td><td>Google&#39;s two steps: retry after a few minutes; disable the VPN or proxy</td></tr><tr><td>You subscribed to AI Pro and still cannot get in</td><td>Flow is not open in every country where AI Pro is sold</td><td>Check the supported list before you buy. If you are in a supported region, contact Google One support</td></tr><tr><td>Without a subscription, you cannot generate video at certain times</td><td>Non-subscribers are restricted during peak hours (about 14:00 to 17:00 UTC)</td><td>Stay clear of 22:00 to 01:00 the next day, Beijing time; you can still generate images and use Agent during that window</td></tr><tr><td>It says you are short of credits</td><td>Video is charged per second or per generation. 8 seconds at 720p on Omni Flash 1.2 is 24 credits</td><td>Check the balance under your profile picture at the top right. Switch to 360p drafts, or to Veo 3.1 Lite at 10 credits a generation</td></tr><tr><td>The generation failed, yet your balance went down</td><td>Official: credits are charged when the generation starts; after a failure or a safety-filter block, the credits are returned within an hour</td><td>Wait an hour. The balance and the charge record may update a little later. If it is still wrong, contact Google One support</td></tr><tr><td>You get &quot;Audio Generation Failed&quot;</td><td>When Veo&#39;s audio quality does not meet the bar, the video is not generated and the credits are returned</td><td>Retry, or change the prompt. If you would rather have a silent video, switch on <strong>Return silent videos</strong> in the project settings; the video is then generated and charged as usual</td></tr><tr><td>The character is inconsistent from shot to shot</td><td>No references were carried between shots</td><td>Create a Character and refer to it with <code>@name</code>, or attach ingredients and start and end frames every time. Use reference images with a clean background and keep the style consistent across them</td></tr><tr><td>One request charged several lots of credits</td><td>The charge is per generation, not per request; asking for 2 candidates means 2 lots</td><td>Set <strong>Number of outputs you want</strong> to 1. Test at 360p first, then go to 720p once you are happy</td></tr><tr><td>You kept retrying because you disliked the result, and the credits soon ran out</td><td>Every retry is a new generation</td><td>Change the prompt first. Send it to Gemini or to Agent in Flow for help with rewriting; the conversation itself costs no credits</td></tr><tr><td>You write prompts in Chinese and the results are unstable</td><td>Google recommends English prompts; results in other languages vary with the language and the complexity</td><td>Write prompts in English. Gemini can translate and rewrite them for you</td></tr><tr><td>You mistook Flow credits for Flow Music credits</td><td>Official: &quot;Google Flow Music credits are separate from your Google AI credits.&quot;</td><td>Keep the two ledgers separate</td></tr><tr><td>You picked a feature and the model was switched automatically</td><td>The current model does not support that feature, so Flow suggests switching to a compatible model</td><td>Before you generate, confirm the model, the resolution and the latest prices in the prompt box settings</td></tr><tr><td>You want a person in an uploaded video to lip-sync and speak new lines</td><td>In all regions, Google does not support editing or generating the speech of people in an uploaded video</td><td>Use a prompt to generate a new video. The picture, background sound, music and sound effects can still be edited</td></tr><tr><td>You generate a celebrity, or edit an uploaded video featuring a minor</td><td>Google does not support this in any region</td><td>Change the subject</td></tr><tr><td>You get &quot;You&#39;re requesting generations too quickly&quot;</td><td>The platform is rate-limiting you, most visibly on zero-credit models</td><td>Wait a while and try again</td></tr><tr><td>A card stays on &quot;Pending&quot;</td><td>There may be a system notification you have not dealt with; failures caused by a policy or a credit limit need manual handling</td><td>Check the system notifications at the top right. Retry by hand, or delete the card</td></tr><tr><td>You added a voice reference and got an error</td><td>Voice references work only for video generations that use ingredients</td><td>Switch to Omni Flash, go through Video and Ingredients, then click Add and Voices</td></tr><tr><td>Extend does not work</td><td>Subscribers only, Omni Flash 1.2 only, web only; Veo Extend retired on 2026-11-05</td><td>Try again once all three are met</td></tr><tr><td>The film you downloaded has a visible watermark</td><td>It is added automatically if you live in India, South Korea or Vietnam and are not on Ultra 20x; in other regions the switch decides</td><td>Check &quot;Visible watermarking&quot; in the profile drop-down menu. The invisible SynthID is always there, and Google asks you not to remove it</td></tr><tr><td>You see an official page saying &quot;you must subscribe to use it&quot;</td><td>That is the wording of an older version of the &quot;Get started&quot; page, still readable from some caches on 2026-11-24</td><td>The live page on the same day agrees with the credits page: without a subscription you can still use basic video generation and editing, with 50 credits a day</td></tr></tbody></table><h2 id="flow-sessions" tabindex="-1">Flow Sessions <a class="header-anchor" href="#flow-sessions" aria-label="Permalink to &quot;Flow Sessions&quot;">​</a></h2><p><strong>Flow Sessions</strong> on the <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">landing page</a> is an artist collaboration programme: a small group of creators are invited to make passion projects with Flow and to work with Google. <strong>It is not an everyday product.</strong> Frontend engineers do not need to learn it separately, and it should not be written up as a tutorial.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>To call Veo or Nano Banana from your own code, go to <a href="./ai-studio.html">AI Studio</a>.</li><li>To decide which plan to subscribe to, see <a href="./google-pro.html">Google AI subscriptions</a>.</li><li>For a clickable prototype, see <a href="./canvas.html">Canvas</a>.</li><li>For where Flow sits in the Gemini family, see the <a href="./gemini-glossary.html">glossary</a>.</li><li>To see how other people write prompts, go to <a href="https://labs.google/flow/tv" target="_blank" rel="noreferrer">Flow TV</a>. Official note: browse the channels with the remote control at the bottom of the screen to see the prompt behind each clip.</li></ul><h2 id="official-resources-and-further-reading" tabindex="-1">Official resources and further reading <a class="header-anchor" href="#official-resources-and-further-reading" aria-label="Permalink to &quot;Official resources and further reading&quot;">​</a></h2><p>Help centre, one line per article:</p><ul><li><a href="https://support.google.com/flow" target="_blank" rel="noreferrer">Flow help centre</a>: the index of every official article.</li><li><a href="https://support.google.com/flow/answer/16353333" target="_blank" rel="noreferrer">Get started with Google Flow</a>: the official Q&amp;A on who can use it, how to get in, errors and watermarks.</li><li><a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos in Google Flow</a>: the steps for the three video generation methods, adding frames, adding reference material and adding voice, plus the official prompt principles.</li><li><a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">Edit videos &amp; build scenes in Google Flow</a>: Extend, editing an existing video, saving frames, Scenebuilder.</li><li><a href="https://support.google.com/flow/answer/16352836" target="_blank" rel="noreferrer">Learn about Google Flow models &amp; supported features</a>: the official mode-by-model support table and retirement dates.</li><li><a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Manage your Google Flow credits</a>: allowances, refresh rules and the charge for each item.</li><li><a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">Where you can use Google Flow</a>: supported languages and countries or regions, plus the feature restrictions by region.</li><li><a href="https://support.google.com/flow/answer/16729550" target="_blank" rel="noreferrer">Create &amp; edit images in Flow</a>: generating and editing images, and the daily caps.</li><li><a href="https://support.google.com/flow/answer/16935308" target="_blank" rel="noreferrer">Manage your Flow projects, assets &amp; collections</a>: projects, assets, Character, downloading, sharing, publishing to YouTube.</li><li><a href="https://support.google.com/flow/answer/17093911" target="_blank" rel="noreferrer">Use the Google Flow Agent</a>: turning Agent on and off, sessions, instructions and default settings.</li><li><a href="https://support.google.com/flow/answer/17104535" target="_blank" rel="noreferrer">Create &amp; manage Tools in Google Flow</a>: creating, editing and sharing Tools.</li><li><a href="https://support.google.com/flow/answer/17102997" target="_blank" rel="noreferrer">Create &amp; use your avatar in Google Flow</a>: putting your own likeness into a video with <code>@me</code>.</li><li><a href="https://support.google.com/flow/answer/17069754" target="_blank" rel="noreferrer">Use keyboard shortcuts in Google Flow</a>: the shortcut table.</li><li><a href="https://support.google.com/flow/answer/17025472" target="_blank" rel="noreferrer">Manage your data in Google Flow</a>: how your data is used and how to delete it.</li><li><a href="https://support.google.com/flow/answer/17571126" target="_blank" rel="noreferrer">Download your Google Flow data</a>: export every project through Google Takeout.</li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro benefits list</a>: the original text of the Flow and Flow Music benefits in Pro.</li></ul><p>Official blog, in time order:</p><ul><li><a href="https://blog.google/innovation-and-ai/products/google-flow-veo-ai-filmmaking-tool/" target="_blank" rel="noreferrer">Meet Flow: AI-powered filmmaking with Veo 3</a>: the launch post from May 2025.</li><li><a href="https://blog.google/innovation-and-ai/products/flow-video-tips/" target="_blank" rel="noreferrer">5 tips for getting started with Flow</a>: 2025-06-25, the official prompt elements, plus the definitions of Jump to and Extend.</li><li><a href="https://blog.google/innovation-and-ai/products/veo-updates-flow/" target="_blank" rel="noreferrer">Introducing Veo 3.1 and advanced capabilities in Flow</a>: 2025-10-15, the official explanation of Ingredients, Frames and Extend.</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/flow-updates-february-2026/" target="_blank" rel="noreferrer">New ways to create and refine content in Flow</a>: 2026-02-25, the interface redesign and image generation folded into Flow.</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/flow-updates/" target="_blank" rel="noreferrer">New agents, mobile apps and Gemini Omni for Google Flow and Google Flow Music</a>: 2026-05-19, the announcement of Agent, Tools and the mobile apps.</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/new-creative-controls-google-flow/" target="_blank" rel="noreferrer">Google Flow brings new creative control features to enhance video editing</a>: 2026-08-27, start and end frames, 1080p and 4K export, 360p drafts.</li><li><a href="https://blog.google/innovation-and-ai/models-and-research/google-labs/" target="_blank" rel="noreferrer">Google Labs blog</a>: follow later updates here.</li></ul><p>Other entry points:</p><ul><li><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">Product entry</a></li><li><a href="https://labs.google/flow/tv" target="_blank" rel="noreferrer">Flow TV</a>: the official showcase page for clips; use the remote control at the bottom of the screen to see the prompt behind each clip. <a href="https://labs.google/fx/faq" target="_blank" rel="noreferrer">labs.google/fx FAQ</a>: the data and policy notes that the help centre points to.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./google-pro.html">Subscriptions and quota</a> — other coding-relevant Pro entitlements</li><li><a href="./canvas.html">Canvas</a> — clickable prototypes</li><li><a href="./gemini-cheatsheet.html#which-tool">Cheatsheet</a> — pick a tool by task</li><li><a href="./ai-studio.html">AI Studio</a> — calling Veo and Nano Banana from code</li><li><a href="./gemini-glossary.html">Glossary</a> — where Flow sits in the Gemini family</li></ul>`,146))])}const k=a(d,[["render",l]]);export{y as __pageData,k as default};
